sys_ui_page.client_script:
// On-demand Xero sync page. Server logic: XeroIntegrationUtils (via XeroOnDemandSyncAjax).
var XS_AJAX = 'x_snc_spm_xero_i_0.XeroOnDemandSyncAjax';
var XS_POLL_MS = 5000;
var xsProjects = [];
var xsSelected = '';
var xsRunning = true;
var xsTimer = null;
var xsWasRunning = false;

var XS_ERRORS = {
    not_authorized: 'You need the it_project_manager role to run a sync.',
    invalid_action: 'Unknown action.',
    running: 'A sync is already running. Wait until it finishes.',
    project_not_found: 'Select a project in the list first.',
    start_failed: 'The sync could not be started. Try again later.',
    no_response: 'No response from the server. Refresh the page.'
};

function xsCall(method, params, callback) {
    var ga = new GlideAjax(XS_AJAX);
    ga.addParam('sysparm_name', method);
    for (var key in params) {
        ga.addParam(key, params[key]);
    }
    ga.getXMLAnswer(function(answer) {
        var result;
        try {
            result = JSON.parse(answer);
        } catch (e) {
            result = { ok: false, error: 'no_response' };
        }
        callback(result || { ok: false, error: 'no_response' });
    });
}

function xsEscape(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text == null ? '' : String(text)));
    return div.innerHTML;
}

function xsRenderList() {
    var filter = (gel('xs_search').value || '').toLowerCase();
    var html = [];
    for (var i = 0; i < xsProjects.length; i++) {
        var p = xsProjects[i];
        var text = ((p.number || '') + ' ' + (p.name || '')).toLowerCase();
        if (filter && text.indexOf(filter) == -1) {
            continue;
        }
        html.push('<tr data-id="' + xsEscape(p.id) + '" class="' + (p.id == xsSelected ? 'xs-selected' : '') +
            '" onclick="xsSelect(this.getAttribute(\'data-id\'))"><td>' + xsEscape(p.number) + '</td><td>' + xsEscape(p.name) + '</td></tr>');
    }
    if (!html.length) {
        html.push('<tr><td colspan="2" class="xs-hint">No project found.</td></tr>');
    }
    gel('xs_rows').innerHTML = html.join('');
}

function xsSelect(id) {
    xsSelected = (xsSelected == id) ? '' : id;
    xsRenderList();
    xsRenderButtons();
}

function xsRenderButtons() {
    gel('xs_btn_update').disabled = xsRunning || !xsSelected;
    gel('xs_btn_fetch').disabled = xsRunning;
    gel('xs_btn_sync').disabled = xsRunning;
    var badge = gel('xs_badge');
    badge.className = 'xs-badge' + (xsRunning ? ' xs-running' : '');
    badge.innerHTML = xsRunning ? 'Sync running' : 'No sync running';
}

function xsRenderResult(last) {
    var box = gel('xs_result');
    if (!last) {
        box.innerHTML = 'No execution yet.';
        return;
    }
    var states = { COMPLETE: 'Complete', ERROR: 'Error', CANCELLED: 'Cancelled', PRESUMED_INTERRUPTED: 'Interrupted' };
    var label = last.type == 'tasks' ? 'Update tasks' : 'Project sync';
    var html = '<div class="xs-hint">' + xsEscape(label) + ' · ' + xsEscape(last.startedAt) + ' · ' +
        xsEscape(states[last.state] || 'Running') + '</div>';
    if (last.state == 'COMPLETE') {
        if (last.type != 'tasks') {
            html += '<div class="xs-row"><span>Projects created</span><b>' + last.projectsCreated + '</b></div>';
        }
        html += '<div class="xs-row"><span>Tasks created</span><b>' + last.tasksCreated + '</b></div>';
        if (last.type != 'tasks') {
            html += '<div class="xs-row"><span>Errors</span><b>' + last.errors + '</b></div>';
        }
        if (last.errors > 0) {
            html += '<div class="xs-alert">' + last.errors + ' project(s) with error. Execution: ' +
                xsEscape(last.startedAt) + ' · ' + xsEscape(last.contextId) + '</div>';
        }
    } else if (states[last.state]) {
        html += '<div class="xs-alert xs-fail">Sync failed. Execution: ' + xsEscape(last.startedAt) + ' · ' +
            xsEscape(last.contextId) + '</div>';
    }
    box.innerHTML = html;
}

function xsRefresh() {
    xsCall('getState', {}, function(state) {
        if (!state.ok) {
            gel('xs_msg').innerHTML = xsEscape(XS_ERRORS[state.error] || state.error);
            return;
        }
        xsRunning = !!state.running;
        if (xsWasRunning && !xsRunning) {
            xsLoadProjects();
        }
        xsWasRunning = xsRunning;
        xsRenderButtons();
        xsRenderResult(state.last);
        clearTimeout(xsTimer);
        if (xsRunning) {
            xsTimer = setTimeout(xsRefresh, XS_POLL_MS);
        }
    });
}

function xsStart(action) {
    gel('xs_msg').innerHTML = '';
    xsRunning = true;
    xsRenderButtons();
    xsCall('startSync', { sysparm_xero_action: action, sysparm_xero_project: action == 'update_tasks' ? xsSelected : '' }, function(result) {
        if (!result.ok) {
            gel('xs_msg').innerHTML = xsEscape(XS_ERRORS[result.error] || result.error);
        }
        xsRefresh();
    });
}

// Reloads the project list from the server (also after a sync ends, so new projects show up).
function xsLoadProjects() {
    xsCall('getProjects', {}, function(result) {
        if (!result.ok) {
            gel('xs_msg').innerHTML = xsEscape(XS_ERRORS[result.error] || result.error);
            return;
        }
        xsProjects = result.projects || [];
        var stillThere = false;
        for (var i = 0; i < xsProjects.length; i++) {
            if (xsProjects[i].id == xsSelected) {
                stillThere = true;
            }
        }
        if (!stillThere) {
            xsSelected = '';
        }
        xsRenderList();
        xsRenderButtons();
    });
}

addLoadEvent(function() {
    if (!gel('xs_rows')) {
        return;
    }
    xsRenderButtons();
    xsLoadProjects();
    xsRefresh();
});
